import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { useState } from 'react';
import { ApiError, createBooking, getSlots } from './api.ts';
import { initialTimeZone } from './booking.ts';

function readSavedZone(): string | null {
  try {
    return localStorage.getItem('tz');
  } catch {
    return null; // storage blocked: fall back to the device zone
  }
}

export function useTimeZone() {
  const deviceTimeZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
  const [timeZone, setZone] = useState(() => initialTimeZone(readSavedZone(), deviceTimeZone));
  const setTimeZone = (tz: string) => {
    setZone(tz);
    try {
      localStorage.setItem('tz', tz);
    } catch {
      // storage blocked: the choice still holds for this visit
    }
  };
  return { timeZone, setTimeZone, deviceTimeZone };
}

export function useSlots() {
  return useQuery({ queryKey: ['slots'], queryFn: getSlots, refetchInterval: 60_000 });
}

export function useBookSlot(onUnavailable: (startsAt: string) => void) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: createBooking,
    onSuccess: ({ booking }) => location.assign('/bookings/' + booking.id),
    onError: (error, variables) => {
      if (error instanceof ApiError && error.status === 409) {
        void queryClient.invalidateQueries({ queryKey: ['slots'] });
        onUnavailable(variables.startsAt);
      }
    },
  });
}
import type { ReactNode } from 'react';
import { cityName, formatDateWithYear, formatTime } from '../shared/time.ts';

export function Card({ children }: { children: ReactNode }) {
  return <div className="mx-auto w-full max-w-[440px] rounded-card border border-line bg-white p-8 shadow-card">{children}</div>;
}

/** Every primary button: full width, 14px bold, 16px vertical padding. */
export const primaryButton = 'block w-full rounded-cta bg-brand py-4 text-center text-sm font-bold text-ink';

export function NotFoundCard({ title }: { title: string }) {
  return (
    <Card>
      <h1 className="text-2xl font-medium">{title}</h1>
      <a href="/" className="mt-4 inline-block font-bold underline underline-offset-4">Back to the home page</a>
    </Card>
  );
}

export function CardTitle() {
  return (
    <h1 className="text-2xl font-medium">
      Book a <span className="underline decoration-brand decoration-4 underline-offset-4">FREE</span> class for your child
    </h1>
  );
}

export function Progress({ step }: { step: 1 | 2 | 3 }) {
  return (
    <div role="img" aria-label={`Step ${step} of 3`} className="mb-6 flex gap-2">
      {[1, 2, 3].map((n) => (
        <span key={n} className={`h-1 w-16 rounded-field ${n <= step ? 'bg-brand' : 'bg-line'}`} />
      ))}
    </div>
  );
}

export function DemoBanner({ now, timeZone }: { now: string; timeZone: string }) {
  const at = new Date(now);
  return (
    <p className="mx-auto mb-4 w-full max-w-[440px] rounded-field bg-brand-50 px-4 py-2 text-center text-sm">
      {`Demo clock: it's ${formatDateWithYear(at, timeZone)}, ${formatTime(at, timeZone)} in ${cityName(timeZone)}`}
    </p>
  );
}

/** Initials in a soft square, for the mentor cards. */
export function Avatar({ name }: { name: string }) {
  const initials = name.split(/\s+/).map((word) => word[0]).slice(0, 2).join('');
  return (
    <span aria-hidden="true" className="flex size-12 shrink-0 items-center justify-center rounded-cta bg-brand-100 font-bold">
      {initials}
    </span>
  );
}
import type { ApiErrorBody, BookingRequest, BookingResponse, ErrorCode, MentorsResponse, SlotsResponse } from '../shared/types.ts';

export class ApiError extends Error {
  status: number;
  code: ErrorCode;
  fields: Record<string, string>;

  constructor(status: number, code: ErrorCode, message: string, fields: Record<string, string> = {}) {
    super(message);
    this.status = status;
    this.code = code;
    this.fields = fields;
  }
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  let res: Response;
  try {
    res = await fetch(path, init);
  } catch {
    // offline or the server is down: a 5xx so queries retry it
    throw new ApiError(503, 'INTERNAL', "We can't reach the server. Check your connection and try again.");
  }
  const body: unknown = await res.json().catch(() => null);
  if (res.ok) {
    if (body === null) throw new ApiError(502, 'INTERNAL', 'Unexpected response from the server.'); // 200 with HTML, say a misrouted proxy
    return body as T;
  }
  const error = (body as ApiErrorBody | null)?.error;
  throw new ApiError(res.status, error?.code ?? 'INTERNAL', error?.message ?? 'Something went wrong. Please try again.', error?.fields);
}

export const getSlots = () => request<SlotsResponse>('/api/slots');
export const getMentors = () => request<MentorsResponse>('/api/mentors');
export const getBooking = (id: string) => request<BookingResponse>('/api/bookings/' + encodeURIComponent(id));
export const createBooking = (body: BookingRequest) =>
  request<BookingResponse>('/api/bookings', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body),
  });
import { ConfirmationPage } from './ConfirmationPage.tsx';
import { NotFoundCard } from './ui.tsx';

export function App() {
  const bookingId = /^\/bookings\/([0-9a-f-]{36})$/.exec(location.pathname)?.[1];
  return (
    <>
      <header className="mx-auto flex max-w-3xl items-center justify-between px-4 py-5">
        <a href="/" className="text-xl font-bold">Codeyoung</a>
        <a href="/mentors" className="text-sm font-medium underline-offset-4 hover:underline">Our mentors</a>
      </header>
      <main className="px-4 pb-12">{bookingId ? <ConfirmationPage id={bookingId} /> : <NotFoundCard title="We couldn't find that page." />}</main>
    </>
  );
}
@import "tailwindcss";

@theme {
  --font-sans: "Satoshi", ui-sans-serif, system-ui, sans-serif;
  --color-brand: #FBB600;      /* main accent: CTAs, selected chip, progress */
  --color-brand-50: #FFF8E6;   /* soft fill: slot-count strip, notices */
  --color-brand-100: #FFE9AD;  /* selected chip */
  --color-ink: #2F4F4F;        /* all text, including on yellow (5:1) */
  --color-ink-soft: #4F6B6B;   /* secondary text (5.5:1 on page) */
  --color-line: #E6E6E6;       /* card border */
  --color-field: #7F9999;      /* field, chip and slot borders (3:1) */
  --color-page: #FAFAFA;       /* page background */
  --color-full: #F1F3F3;       /* full slot / full day */
  --color-alert: #B42318;
  --color-alert-50: #FEF3F2;
  --radius-card: 24px;
  --radius-cta: 16px;
  --radius-field: 8px;
  --shadow-card: 0 6px 8px rgba(0, 0, 0, 0.02);
}

@layer base {
  body {
    @apply bg-page text-ink antialiased;
  }

  /* ink, not brand, carries the 3:1 contrast WCAG 1.4.11 asks of a focus ring (brand on white is 1.78:1); the brand halo fills the gap */
  :focus-visible {
    outline: 2px solid var(--color-ink);
    outline-offset: 2px;
    box-shadow: 0 0 0 4px var(--color-brand);
  }
}
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { App } from './App.tsx';
import { ApiError } from './api.ts';
import './index.css';

// a 4xx is the server's answer, so asking again would only repeat it
const queryClient = new QueryClient({
  defaultOptions: {
    queries: { retry: (failures, error) => failures < 3 && !(error instanceof ApiError && error.status < 500) },
  },
});

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <QueryClientProvider client={queryClient}>
      <App />
    </QueryClientProvider>
  </StrictMode>,
);

