async (page) => {
  const b = await page.context().newPage();
  await b.goto('http://localhost:5173/');
  await b.getByLabel("Parent's name").fill('Ben Clarke');
  await b.getByLabel("Parent's email").fill('ben@example.com');
  await b.getByLabel("Child's name").fill('Mia');
  await b.getByRole('button', { name: 'Choose a time' }).click();
  await b.locator('label:has(input[value="2026-10-28"])').click();
  await b.locator('label:has(input[value="2026-10-28T17:00:00.000Z"])').click();
  // tab A (Asha) picks the same hour
  await page.bringToFront();
  await page.locator('label:has(input[value="2026-10-28"])').click();
  await page.locator('label:has(input[value="2026-10-28T17:00:00.000Z"])').click();
  const aLabel = await page.locator('button:has-text("Confirm")').innerText();
  // tab B confirms first
  await b.bringToFront();
  await b.getByRole('button', { name: /^Confirm/ }).click();
  await b.waitForURL(/\/bookings\//);
  await b.getByText("You're booked!").waitFor();
  const bUrl = b.url();
  await b.screenshot({ path: '.playwright-mcp/task-11-shots/4a-tab-b-booked.png', fullPage: true });
