21	export function BookingPage() {
22	  const [state, dispatch] = useReducer(flowReducer, initialFlow);
23	  const { timeZone, setTimeZone, deviceTimeZone } = useTimeZone();
24	  const { data, error, isFetching, refetch } = useSlots();
25	  const book = useBookSlot((startsAt) => {
26	    dispatch({ type: 'daySelected', dayKey: localDate(new Date(startsAt), timeZone) }); // stay on that day, even if it is now full
27	    dispatch({ type: 'slotUnavailable', startsAt });
28	  });
29	  // TanStack tells React about a pending mutation after a setTimeout(0), so a quick second click lands before the button disables
30	  const sending = useRef(false);
31	  const heading = useRef<HTMLHeadingElement>(null);
32	  const dayRow = useRef<HTMLDivElement>(null);
33	  const confirmButton = useRef<HTMLButtonElement>(null);
34	  const focusedStep = useRef(state.step);
35	  useEffect(() => {
36	    if (focusedStep.current === state.step) return; // the first load leaves focus alone
37	    focusedStep.current = state.step;
38	    heading.current?.focus();
39	  }, [state.step]);
40	
41	  const frame = (children: ReactNode) => (
42	    <>
43	      {data?.demo && <DemoBanner now={data.now} timeZone={timeZone} />}
44	      <Card>
45	        <Progress step={state.step === 'details' ? 1 : 2} />
46	        <CardTitle />
47	        {children}
48	      </Card>
49	    </>
50	  );
51	
52	  if (state.step === 'details') {
53	    return frame(
54	      <>
55	        <h2 ref={heading} tabIndex={-1} className="mt-6 text-lg font-bold">Your details</h2>
56	        <DetailsForm
57	          details={state.details}
58	          errors={fieldErrors(book.error)}
59	          onSubmit={(details) => {
60	            book.reset();
61	            dispatch({ type: 'detailsSubmitted', details });
62	          }}
63	        />
64	      </>,
65	    );
66	  }
67	
68	  const header = (
69	    <div className="mt-6 flex items-center gap-1">
70	      <button type="button" aria-label="Back to your details" onClick={() => dispatch({ type: 'back' })} className="-ml-2 rounded-field p-1 hover:bg-brand-50">
71	        <Icon><path d="m12 19-7-7 7-7" /><path d="M19 12H5" /></Icon>
72	      </button>
73	      <h2 ref={heading} tabIndex={-1} className="text-lg font-bold">Pick a time</h2>
74	    </div>
75	  );
76	
77	  if (!data) {
78	    return frame(
79	      <>
80	        {header}
81	        {error && !isFetching ? (
82	          <div className="mt-6">
83	            <p role="alert">We couldn't load times.</p>
84	            <button type="button" onClick={() => void refetch()} className="mt-2 font-bold underline underline-offset-4">Try again</button>
85	          </div>
86	        ) : (
87	          <p role="status" className="mt-6">Loading times…</p>
88	        )}
89	      </>,
90	    );
91	  }
92	
93	  const now = new Date(data.now);
94	  const days = groupIntoDays(data.slots, timeZone, now);
95	  const shownSlots = days.flatMap((d) => d.slots);
96	  const key = shownDayKey(days, state.selected, state.chosenDay, timeZone);
97	  const day = days.find((d) => d.key === key)!;
98	  // after a zone change the selected time can fall outside the 14 days shown; then nothing counts as selected
99	  const selected = shownSlots.some((s) => s.startsAt === state.selected) ? state.selected : null;
100	  const change = clockChange(days, timeZone, now);
101	  const busy = book.isPending || book.isSuccess;
102	  const bookError = book.error;
103	  const deviceCity = cityName(deviceTimeZone);
104	
105	  const confirm = () => {
106	    if (!selected || sending.current) return;
107	    sending.current = true;
108	    book.mutate(
109	      { startsAt: selected, ...state.details, parentTimeZone: timeZone },
110	      {
111	        onError: (err) => {
112	          sending.current = false;
113	          if (hasDetailErrors(err)) dispatch({ type: 'back' });
114	        },
115	      },
116	    );
117	  };
118	
119	  return frame(
120	    <>
121	      {header}
122	      <div className="mt-4">
123	        <ZonePill timeZone={timeZone} now={now} onChange={setTimeZone} />
124	        {isValidTimeZone(deviceTimeZone) && !sameZone(timeZone, deviceTimeZone) && (
125	          <p className="mt-2 text-sm text-ink-soft">
126	            Your device is set to {deviceCity} time.{' '}
127	            <button type="button" onClick={() => setTimeZone(deviceTimeZone)} className="font-bold text-ink underline underline-offset-4">
128	              Use {deviceCity} time
129	            </button>
130	          </p>
131	        )}
132	      </div>
133	
134	      <DayChips days={days} value={key} rowRef={dayRow} onChange={(dayKey) => dispatch({ type: 'daySelected', dayKey })} />
135	
136	      {change && key >= change.dayKey && (
137	        <p className="mt-4 rounded-field bg-brand-50 p-3 text-sm">
138	          Clocks in {cityName(timeZone)} change on {formatDayKey(change.dayKey)}. Times from then on are {change.to}, not {change.from}.
139	          {dayMixesOffsets(day, timeZone) && ' On this day each time shows its zone.'}
140	        </p>
141	      )}
142	
143	      {day.openCount > 0 ? (
144	        <SlotGrid
145	          day={day}
146	          timeZone={timeZone}
147	          selected={state.selected}
148	          onSelect={(startsAt) => dispatch({ type: 'slotSelected', startsAt })}
149	        />
150	      ) : (
151	        <EmptyDay
152	          days={days}
153	          dayKey={key}
154	          onJump={(dayKey) => {
155	            dispatch({ type: 'daySelected', dayKey });
156	            dayRow.current?.querySelector<HTMLInputElement>(`input[value="${dayKey}"]`)?.focus(); // the button that had focus goes away
157	          }}
158	        />
159	      )}
160	
161	      {state.unavailable && (
162	        <UnavailableAlert
163	          startsAt={state.unavailable}
164	          alternatives={nearestOpenTimes(shownSlots, state.unavailable)}
165	          timeZone={timeZone}
166	          shownKey={key}
167	          onPick={(startsAt) => {
168	            flushSync(() => dispatch({ type: 'slotSelected', startsAt })); // Confirm is disabled until this renders, and a disabled button takes no focus
169	            confirmButton.current?.focus(); // the alert holding the clicked button goes away
170	          }}
171	        />
172	      )}
173	      {bookError && !(bookError instanceof ApiError && bookError.status === 409) && !hasDetailErrors(bookError) && (
174	        <p role="alert" className="mt-4 text-sm text-alert">{bookError.message}</p>
175	      )}
176	
177	      <button
178	        ref={confirmButton}
179	        type="button"
180	        disabled={!selected || busy}
181	        onClick={confirm}
182	        className={`mt-6 ${primaryButton} disabled:cursor-not-allowed disabled:bg-full disabled:text-ink-soft`}
183	      >
184	        {busy ? 'Booking…' : selected ? `Confirm ${formatWhenShort(new Date(selected), timeZone)}` : 'Choose a time'}
185	      </button>
186	    </>,
187	  );
188	}
189	
190	/** 'Tue 27 Oct, 4:00 PM GMT' */
191	function formatWhenShort(at: Date, tz: string): string {
192	  return `${formatDate(at, tz)}, ${formatTime(at, tz)} ${zoneAbbreviation(at, tz)}`;
193	}
194	
195	function DetailsForm({ details, errors, onSubmit }: { details: Details; errors: Record<string, string>; onSubmit: (details: Details) => void }) {
196	  const submit = (event: FormEvent<HTMLFormElement>) => {
197	    event.preventDefault();
198	    const form = new FormData(event.currentTarget);
199	    const value = (name: keyof Details) => String(form.get(name)).trim();
200	    onSubmit({ parentName: value('parentName'), parentEmail: value('parentEmail'), childName: value('childName') });
201	  };
202	  return (
203	    <form onSubmit={submit} className="mt-4 flex flex-col gap-4">
204	      <Field name="parentName" label="Parent's name" autoComplete="name" defaultValue={details.parentName} error={errors.parentName} />

message.content:
The coordinator sent a message while you were working:
Fix round 1 for Task 11. The opus review found the page meets the brief, the spec copy and every ruling, and your screenshots back the checks. It found one real defect. Make these two changes in one new commit on main.

1. **Important: the double-submit ref can leave Confirm dead.** `sending.current` is cleared only in the per-call `mutate` `onError`. The Back button (around `BookingPage.tsx:70`) stays enabled while a booking is pending. Pressing Back and resubmitting step 1 calls `book.reset()` (around :60), and that detaches the observer from the running mutation (see `@tanstack/query-core` `mutationObserver.js`). When that request then fails, the per-call `onError` never fires, `sending` stays `true`, and Confirm looks enabled but does nothing until reload. Fix: put `disabled={busy}` on the Back button so `reset()` can't run while a booking is in flight or has succeeded. **Don't** fix it by clearing the ref in `onSubmit`: `reset()` also clears `isPending`, so that would allow a second POST, which is the double booking from Review Focus 1.
2. **Keep the selected day chip in view after a zone change.** In your screenshot 2b the Sun 25 grid shows while its chip has scrolled out of view, so nothing on screen names the day. Route both zone setters (the select's `onChange` and the "Use {city} time" button) through one helper:
   ```ts
   const changeZone = (tz: string) => {
     flushSync(() => setTimeZone(tz));
     dayRow.current?.querySelector('input:checked')?.parentElement?.scrollIntoView({ block: 'nearest', inline: 'nearest' });
   };
   ```
   Adapt the names to your code. This follows the same pattern as your alternative-pick focus, and needs no effect.

Keep the two copy extras: the zone abbreviation in the 409 heading, and "1 time". The controller ruled to keep both. Leave the whitespace-only names and `flushSync` as they are.

Re-run `npm run typecheck && npm run build` and `npm test` (all three zones). If the browser tool is still allowed, re-check the zone-change case (London → New York with a far-right day selected) and take one screenshot. Use the same setup as before: start servers in the background, kill only the PIDs you captured, and keep screenshots under `.playwright-mcp/task-11-shots/`. If a browser action is denied, don't work around it; say so in the report.

Suggested message: `fix(web): lock back while a booking is in flight and keep the chosen day in view`. The usual rules apply: lowercase, no trailer, files added by name. Append the fix report to task-11-report.md, then reply with the short status contract.

Address this before completing your current task.

